  if (!Array.isArray(g) || g.length < 1 || g.length > 30000) return 'g needs 1 to 3 * 10^4 values.';
  if (!Array.isArray(s) || s.length > 30000) return 's has at most 3 * 10^4 values.';
  const ok = v => Number.isInteger(v) && v >= 1 && v <= 2147483647;
  if (!g.every(ok)) return 'Each greed value is an integer from 1 to 2^31 - 1.';
  if (!s.every(ok)) return 'Each cookie size is an integer from 1 to 2^31 - 1.';
  return null;
}

