function findContentChildren(g, s) {
  // k children can be made happy exactly when the k least greedy children, matched in order,
  // fit the k biggest cookies; try every k from the largest possible down.
  const greed = [...g].sort((a, b) => a - b);
  const sizes = [...s].sort((a, b) => b - a);
  for (let k = Math.min(greed.length, sizes.length); k > 0; k--) {
    const biggest = sizes.slice(0, k).reverse();
    let fits = true;
    for (let i = 0; i < k; i++) if (biggest[i] < greed[i]) { fits = false; break; }
    if (fits) return k;
  }
  return 0;
}

