  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const top = [100, 10000, 2147483647][int(0, 2)];
    const g = Array.from({ length: int(1500, 2000) }, () => int(1, top));
    const s = Array.from({ length: int(0, 2000) }, () => int(1, top));
    return [g, s];
  }
  const hi = int(1, 10);
  const value = () => rand() < 0.08 ? 2147483647 : int(1, hi);
  const g = Array.from({ length: int(1, 7) }, value);
  const s = Array.from({ length: int(0, 7) }, value);
  return [g, s];
}
